import{D as e,E as t,On as n,T as r,Zn as i,_ as a,b as o,k as s,mt as c,qt as l,tr as u,vn as d,y as f}from"./Car86Ubo.js";import{t as p}from"./jT-8CCmP.js";import{c as m,t as h}from"#entry";import{t as g}from"./DsIk34El.js";import{t as _}from"./CNs_Ozdc.js";var v={class:`ads-playbook-page`},y={class:`playbook-hero`},b={class:`hero-left`},x={class:`hero-sub`},S={class:`hero-actions`},C={class:`playbook-nav`},w={class:`playbook-body`},T={key:0,class:`tab-section`},E={key:1,class:`tab-section`},D={key:2,class:`tab-section`},O={key:3,class:`tab-section`},k=h(s({__name:`ads-playbook`,setup(s){_({middleware:`auth`});let{l:h}=g(),k=d(`routine`);return(s,d)=>{let g=m;return c(),o(`div`,v,[a(`header`,y,[a(`div`,b,[d[4]||=a(`span`,{class:`hero-eyebrow`},` MEDIA BUYER DAILY SOP & PLAYBOOK`,-1),d[5]||=a(`h1`,{class:`hero-title`},[a(`span`,null,`ຄູ່ມືຍິງແອດປະຈຳວັນ`),a(`span`,{class:`hero-badge`},`Standard Operating Procedure`)],-1),a(`p`,x,u(n(h)({lo:`ຂັ້ນຕອນການເຮັດວຽກໃນ 1 ມື້ຂອງຄົນຍິງແອດ, ວິທີອ່ານຕົວເລກ, ກົດການຕັດສິນໃຈ Kill/Hold/Scale ແລະ ວິທີກັ່ນຕອງທັກຜີ`,th:`ขั้นตอนการทำงานใน 1 วันของคนยิงแอด, วิธีอ่านตัวเลข, กฎการตัดสินใจ Kill/Hold/Scale และวิธีกรองทักผี`,en:`Daily media buyer routine, metric diagnostics, Kill/Hold/Scale decision tree, and ghost lead protocol`})),1)]),a(`div`,S,[e(g,{to:`/ads-battle`},{default:l(()=>[e(p,{color:`primary`,variant:`flat`,"prepend-icon":`mdi-scale-balance`,class:`font-weight-bold`},{default:l(()=>[...d[6]||=[t(` ໄປໜ້າ Ads Battle `,-1)]]),_:1})]),_:1}),e(g,{to:`/live-chat`},{default:l(()=>[e(p,{variant:`outlined`,"prepend-icon":`mdi-chat-processing-outline`},{default:l(()=>[...d[7]||=[t(` ໄປໜ້າ Live Chat `,-1)]]),_:1})]),_:1})])]),a(`nav`,C,[a(`button`,{type:`button`,class:i([`nav-tab-btn`,{active:n(k)===`routine`}]),onClick:d[0]||=e=>k.value=`routine`},[...d[8]||=[a(`span`,{class:`tab-icon`},null,-1),a(`span`,null,`1. ຕາຕະລາງປະຈຳວັນ (Daily Routine)`,-1)]],2),a(`button`,{type:`button`,class:i([`nav-tab-btn`,{active:n(k)===`metrics`}]),onClick:d[1]||=e=>k.value=`metrics`},[...d[9]||=[a(`span`,{class:`tab-icon`},null,-1),a(`span`,null,`2. ວິທີອ່ານ 4 ຕົວເລກ (Diagnostics)`,-1)]],2),a(`button`,{type:`button`,class:i([`nav-tab-btn`,{active:n(k)===`decision`}]),onClick:d[2]||=e=>k.value=`decision`},[...d[10]||=[a(`span`,{class:`tab-icon`},null,-1),a(`span`,null,`3. ກົດເຫຼັກຕັດສິນໃຈ (Kill, Hold, Scale)`,-1)]],2),a(`button`,{type:`button`,class:i([`nav-tab-btn`,{active:n(k)===`ghost`}]),onClick:d[3]||=e=>k.value=`ghost`},[...d[11]||=[a(`span`,{class:`tab-icon`},null,-1),a(`span`,null,`4. ວິທີຈັດການ "ທັກຜີ" & ມືຫຼົງກົດ`,-1)]],2)]),a(`main`,w,[n(k)===`routine`?(c(),o(`section`,T,[...d[12]||=[r(`<div class="section-header" data-v-2560293b><h2 data-v-2560293b> ຕາຕະລາງປະຈຳວັນ: ມື້ໜຶ່ງຄວນເບິ່ງແອດຈັກເທື່ອ?</h2><p class="section-lead" data-v-2560293b> ກົດເຫຼັກ: <strong data-v-2560293b>ຢ່າເປີດເບິ່ງແອດທຸກໆ 10 ນາທີ</strong> ເພາະຈະເຮັດໃຫ້ທ່ານ &quot;ໃຊ້ອາລົມ&quot; ຕັດສິນ. ໃຫ້ເບິ່ງພຽງ 3 ຄັ້ງຕໍ່ມື້ຕາມຕາຕະລາງນີ້: </p></div><div class="time-cards-grid" data-v-2560293b><div class="time-card morning" data-v-2560293b><div class="time-badge morning" data-v-2560293b><span data-v-2560293b> 08:30 - 09:30 (ຕອນເຊົ້າ)</span><strong data-v-2560293b>ກວດສອບສະພາບລວມ</strong></div><div class="card-content" data-v-2560293b><h4 data-v-2560293b>ສິ່ງທີ່ຕ້ອງເຮັດ:</h4><ul data-v-2560293b><li data-v-2560293b>ເປີດເບິ່ງໜ້າ Ads Battle ເລືອກວັນທີ <strong data-v-2560293b>&quot;ມື້ວານນີ້ (Yesterday)&quot;</strong>.</li><li data-v-2560293b>ເຊັກຍອດໃຊ້ຈ່າຍລວມ, ຈຳນວນອໍເດີ, ແລະ CPA ສະເລ່ຍຂອງມື້ວານ.</li><li data-v-2560293b>ກວດສອບວ່າມີແອດໃດຕິດບັນຫາບໍ່ (ເຊັ່ນ ຖືກ Disapprove ຫຼື ບັດຕັດເງິນບໍ່ຜ່ານ).</li></ul><div class="rule-box warn" data-v-2560293b><strong data-v-2560293b>ກົດຫ້າມຕອນເຊົ້າ:</strong> ຫ້າມປິດແອດທີ່ຫາກໍ່ເປີດໃໝ່ ຫຼື ປັບງົບຕອນເຊົ້າເດັດຂາດ! ເພາະແອດຫາກໍ່ເລີ່ມແລ່ນ ຄ່າແອດຈະຍັງແພງຢູ່. </div></div></div><div class="time-card afternoon" data-v-2560293b><div class="time-badge afternoon" data-v-2560293b><span data-v-2560293b> 10:00 - 18:00 (ຕອນກາງເວັນ)</span><strong data-v-2560293b>ປິດການຂາຍ &amp; ກັ່ນຕອງທັກຜີ</strong></div><div class="card-content" data-v-2560293b><h4 data-v-2560293b>ສິ່ງທີ່ຕ້ອງເຮັດ:</h4><ul data-v-2560293b><li data-v-2560293b><strong data-v-2560293b>Speed to Lead:</strong> ຕອບແຊັດໃຫ້ໄວພາຍໃນ 60 ວິນາທີ ເພາະລູກຄ້າເລື່ອນເບິ່ງຫຼາຍເພຈພ້ອມກັນ.</li><li data-v-2560293b><strong data-v-2560293b>ກົດ 15 ນາທີແຍກທັກຜີ:</strong> ສົ່ງລາຄາສິນຄ້າ + ໂປຣໂມຊັ່ນສົ່ງຟຣີ. ຖ້າເຂົາອ່ານແລ້ວມິດເກີນ 15 ນາທີ ➔ <strong data-v-2560293b>Move on ທັນທີ</strong> ບໍ່ຕ້ອງນັ່ງຖ້າ.</li><li data-v-2560293b><strong data-v-2560293b>ລູກຄ້າແທ້:</strong> ເມື່ອລູກຄ້າໃຫ້ເບີໂທ ➔ ກົດສ້າງອໍເດີໃນລະບົບທັນທີ ເພື່ອສົ່ງສັນຍານ CAPI ບອກ Facebook.</li></ul><div class="rule-box info" data-v-2560293b><strong data-v-2560293b>Tip:</strong> ຖ້າພົບຄົນກວນເມືອງ ຫຼື ເດັກນ້ອຍຫຼິ້ນເກມ ➔ ກົດ <strong data-v-2560293b>Ban from Page</strong> ທັນທີ. </div></div></div><div class="time-card evening" data-v-2560293b><div class="time-badge evening" data-v-2560293b><span data-v-2560293b> 20:30 - 21:30 (ຕອນຄ່ຳ)</span><strong data-v-2560293b>ເວລາຕັດສິນໃຈ (Kill, Hold, Scale)</strong></div><div class="card-content" data-v-2560293b><h4 data-v-2560293b>ສິ່ງທີ່ຕ້ອງເຮັດ:</h4><ul data-v-2560293b><li data-v-2560293b>ເປີດເບິ່ງໜ້າ <strong data-v-2560293b>Ads Battle</strong> ເລືອກວັນທີ &quot;ມື້ນີ້ (Today)&quot;.</li><li data-v-2560293b><strong data-v-2560293b> KILL:</strong> ແອດທີ່ໃຊ້ງົບ $6.00 - $8.00 ແລ້ວຍັງ 0 ອໍເດີ ➔ ກົດປິດທັນທີ!</li><li data-v-2560293b><strong data-v-2560293b> HOLD:</strong> ແອດທີ່ຫາກໍ່ໃຊ້ງົບ $1 - $3 ➔ ປ່ອຍແລ່ນຕໍ່ໃຫ້ຄົບ 48 ຊົ່ວໂມງ.</li><li data-v-2560293b><strong data-v-2560293b> SCALE:</strong> ແອດນາງຟ້າທີ່ມີ 2-3 ອໍເດີ ແລະ CPA ຖືກ ➔ ກົດ Scale ເພີ່ມງົບ +20%.</li></ul><div class="rule-box success" data-v-2560293b><strong data-v-2560293b>ເຫດຜົນ:</strong> ການປັບງົບຕອນ 21:00 ຈະເຮັດໃຫ້ລະບົບ Meta Bidding ເລີ່ມຕົ້ນງົບໃໝ່ຢ່າງສະໝ່ຳສະເໝີໃນວັນຕໍ່ໄປ (00:00). </div></div></div></div>`,2)]])):f(``,!0),n(k)===`metrics`?(c(),o(`section`,E,[...d[13]||=[r(`<div class="section-header" data-v-2560293b><h2 data-v-2560293b> ວິທີອ່ານ 4 ຕົວເລກຫຼັກ: ຮູ້ທັນທີວ່າແອດຕິດບັນຫາບ່ອນໃດ!</h2><p class="section-lead" data-v-2560293b> ເວລາ CPA (ຕົ້ນທຶນຕໍ່ອໍເດີ) ແພງ, ຢ່າຟ້າວດ່ວນສະຫຼຸບວ່າ &quot;ແອດບໍ່ດີ&quot;. ໃຫ້ໄລ່ກວດ 4 ຂັ້ນຕອນນີ້ຕາມລຳດັບ: </p></div><div class="funnel-chain" data-v-2560293b><div class="funnel-step" data-v-2560293b><span class="step-num" data-v-2560293b>1</span><strong data-v-2560293b>CPM (ຄ່າສະແດງຜົນ)</strong><small data-v-2560293b>ຄ່າເຫັນ 1,000 ເທື່ອ</small></div><div class="funnel-arrow" data-v-2560293b>➔</div><div class="funnel-step" data-v-2560293b><span class="step-num" data-v-2560293b>2</span><strong data-v-2560293b>Link CTR (ອັດຕາການຄລິກ)</strong><small data-v-2560293b>ຄົນຢຸດເບິ່ງ &amp; ກົດ</small></div><div class="funnel-arrow" data-v-2560293b>➔</div><div class="funnel-step" data-v-2560293b><span class="step-num" data-v-2560293b>3</span><strong data-v-2560293b>Cost per Message</strong><small data-v-2560293b>ຕົ້ນທຶນຕໍ່ຄົນທັກ</small></div><div class="funnel-arrow" data-v-2560293b>➔</div><div class="funnel-step" data-v-2560293b><span class="step-num" data-v-2560293b>4</span><strong data-v-2560293b>Closing Rate &amp; CPA</strong><small data-v-2560293b>ປິດການຂາຍ &amp; ກຳໄລ</small></div></div><div class="metrics-grid mt-4" data-v-2560293b><div class="metric-card" data-v-2560293b><div class="metric-top" data-v-2560293b><span class="metric-tag" data-v-2560293b>ຂັ້ນທີ 1</span><h4 data-v-2560293b>1. CPM (Cost per 1,000 Impressions)</h4></div><p class="metric-desc" data-v-2560293b> ບອກວ່າ <strong data-v-2560293b>&quot;ກຸ່ມເປົ້າໝາຍແພງ ຫຼື ຖືກ&quot;</strong> (ຄ່າສະແດງຜົນໃຫ້ຄົນເຫັນ 1,000 ເທື່ອ). </p><div class="metric-benchmarks" data-v-2560293b><div class="bm-row green" data-v-2560293b><span data-v-2560293b> ດີຫຼາຍ:</span> <strong data-v-2560293b>$1.00 - $3.00 (22,000 - 66,000 ₭)</strong></div><div class="bm-row red" data-v-2560293b><span data-v-2560293b> ແພງຜິດປົກກະຕິ:</span> <strong data-v-2560293b>$6.00 - $10.00+</strong></div></div><div class="metric-fix" data-v-2560293b><strong data-v-2560293b>ວິທີແກ້ຖ້າ CPM ແພງ:</strong> ປິດ Audience Network ທັນທີ, ຂະຫຍາຍອາຍຸເປັນ 23-48 ປີ, ຫຼື ຍິງແບບ Broad ບໍ່ຕ້ອງໃສ່ Interest. </div></div><div class="metric-card" data-v-2560293b><div class="metric-top" data-v-2560293b><span class="metric-tag" data-v-2560293b>ຂັ້ນທີ 2</span><h4 data-v-2560293b>2. Link CTR (Click-Through Rate)</h4></div><p class="metric-desc" data-v-2560293b> ບອກວ່າ <strong data-v-2560293b>&quot;ຄລິບວິດີໂອ ຫຼື ຮູບພາບ ໜ້າສົນໃຈບໍ່&quot;</strong> (ຄົນເຫັນ 100 ຄົນ ກົດຈັກຄົນ). </p><div class="metric-benchmarks" data-v-2560293b><div class="bm-row green" data-v-2560293b><span data-v-2560293b> ດີຫຼາຍ:</span> <strong data-v-2560293b>2.0% - 4.0%+ (ແອດດຶງດູດສາຍຕາ)</strong></div><div class="bm-row yellow" data-v-2560293b><span data-v-2560293b> ປານກາງ:</span> <strong data-v-2560293b>1.0% - 1.8%</strong></div><div class="bm-row red" data-v-2560293b><span data-v-2560293b> ຄົນເລື່ອນຜ່ານ:</span> <strong data-v-2560293b>ຕ່ຳກວ່າ 0.9%</strong></div></div><div class="metric-fix" data-v-2560293b><strong data-v-2560293b>ວິທີແກ້ຖ້າ CTR ຕ່ຳ:</strong> ປ່ຽນ 3 ວິນາທີທຳອິດຂອງວິດີໂອ (Hook) ຫຼື ປ່ຽນຮູບໜ້າປົກ (Thumbnail) ໃໝ່ທັນທີ. </div></div><div class="metric-card" data-v-2560293b><div class="metric-top" data-v-2560293b><span class="metric-tag" data-v-2560293b>ຂັ້ນທີ 3</span><h4 data-v-2560293b>3. Cost per Message (ຕົ້ນທຶນຕໍ່ຄົນທັກ)</h4></div><p class="metric-desc" data-v-2560293b> ບອກວ່າ <strong data-v-2560293b>&quot;ຄົນສົນໃຈຢາກຊື້ຫຼາຍໜ້ອຍປານໃດ&quot;</strong> ສຳລັບສິນຄ້າ Smartwatch / Gadget. </p><div class="metric-benchmarks" data-v-2560293b><div class="bm-row green" data-v-2560293b><span data-v-2560293b> ດີຫຼາຍ:</span> <strong data-v-2560293b>$0.20 - $0.50 (4,500 - 11,000 ₭/ທັກ)</strong></div><div class="bm-row yellow" data-v-2560293b><span data-v-2560293b> ພໍຮັບໄດ້:</span> <strong data-v-2560293b>$0.60 - $0.90</strong></div><div class="bm-row red" data-v-2560293b><span data-v-2560293b> ແພງເກີນໄປ:</span> <strong data-v-2560293b>ເກີນ $1.20 - $2.00+ ຕໍ່ທັກ</strong></div></div><div class="metric-fix" data-v-2560293b><strong data-v-2560293b>ວິທີແກ້ຖ້າຄ່າທັກແພງ:</strong> ປັບ Headline ຂໍ້ຄວາມເທິງແອດ, ເນັ້ນໂປຣໂມຊັ່ນສົ່ງຟຣີ, ແລະ ໃສ່ລາຄາຈະແຈ້ງ. </div></div><div class="metric-card" data-v-2560293b><div class="metric-top" data-v-2560293b><span class="metric-tag" data-v-2560293b>ຂັ້ນທີ 4</span><h4 data-v-2560293b>4. Closing Rate &amp; Real CPA</h4></div><p class="metric-desc" data-v-2560293b> ບອກວ່າ <strong data-v-2560293b>&quot;ທີມຂາຍປິດໄດ້ດີບໍ່ ແລະ ໄດ້ກຳໄລແທ້ບໍ່&quot;</strong> (ຄົນທັກ 10 ຄົນ ປິດໄດ້ຈັກຄົນ). </p><div class="metric-benchmarks" data-v-2560293b><div class="bm-row green" data-v-2560293b><span data-v-2560293b> ທີມຂາຍເກັ່ງ:</span> <strong data-v-2560293b>20% - 30% (CPA ຕ່ຳກວ່າກຳໄລ)</strong></div><div class="bm-row red" data-v-2560293b><span data-v-2560293b> ຮົ່ວໄຫຼ (ອັນຕະລາຍ):</span> <strong data-v-2560293b>ຕ່ຳກວ່າ 10% (ທັກ 20 ຄົນ ຊື້ 1 ຄົນ)</strong></div></div><div class="metric-fix" data-v-2560293b><strong data-v-2560293b>ວິທີແກ້ຖ້າ Closing Rate ຕ່ຳ:</strong> ແອດບໍ່ໄດ້ຜິດ! ແຕ່ບົດຕອບແຊັດຊ້າ ຫຼື ບໍ່ສ້າງຄວາມໝັ້ນໃຈ ➔ ຕ້ອງເນັ້ນ *&quot;ກວດເຄື່ອງກ່ອນຈ່າຍໄດ້&quot;*. </div></div></div>`,3)]])):f(``,!0),n(k)===`decision`?(c(),o(`section`,D,[...d[14]||=[r(`<div class="section-header" data-v-2560293b><h2 data-v-2560293b> ກົດເຫຼັກການຕັດສິນໃຈ: 3 ຄຳສັ່ງ (Kill, Hold, Scale)</h2><p class="section-lead" data-v-2560293b> ທຸກໆຄ່ຳ (21:00), ໃຫ້ເປີດເບິ່ງໜ້າ Ads Battle ແລ້ວໃຊ້ກົດເຫຼັກນີ້ຕັດສິນທັນທີ ໂດຍບໍ່ໃຊ້ອາລົມ: </p></div><div class="decision-cards" data-v-2560293b><div class="decision-card kill" data-v-2560293b><div class="decision-header" data-v-2560293b><span class="d-icon" data-v-2560293b></span><div data-v-2560293b><h3 data-v-2560293b>1. ຄຳສັ່ງ KILL (ປິດແອດຖິ້ມທັນທີ)</h3><small data-v-2560293b>ຢຸດງົບປະມານຮົ່ວໄຫຼ</small></div></div><div class="decision-criteria" data-v-2560293b><h4 data-v-2560293b>ເງື່ອນໄຂທີ່ຕ້ອງປິດ:</h4><ul data-v-2560293b><li data-v-2560293b>ແອດທີ່ໃຊ້ງົບໄປຮອດ <strong data-v-2560293b>$6.00 - $8.00+ ແລ້ວຍັງ 0 ອໍເດີ</strong> ➔ ປິດທັນທີ!</li><li data-v-2560293b>ແອດທີ່ <strong data-v-2560293b>Link CTR ຕ່ຳກວ່າ 0.8%</strong> ຕິດຕໍ່ກັນ 2 ມື້ (ຄົນບໍ່ສົນໃຈ) ➔ ປິດທັນທີ!</li><li data-v-2560293b>ແອດທີ່ <strong data-v-2560293b>Frequency (ຄວາມຖີ່) ສູງເກີນ 2.5x</strong> (ຄົນເຫັນຊ້ຳໆຈົນເບື່ອ) ➔ ປິດແລ້ວປ່ຽນຄລິບໃໝ່!</li></ul></div></div><div class="decision-card hold" data-v-2560293b><div class="decision-header" data-v-2560293b><span class="d-icon" data-v-2560293b></span><div data-v-2560293b><h3 data-v-2560293b>2. ຄຳສັ່ງ HOLD (ປ່ອຍແລ່ນຕໍ່ ຫ້າມປິດ!)</h3><small data-v-2560293b>ໃຫ້ເວລາ AI ຮຽນຮູ້ (Learning Phase)</small></div></div><div class="decision-criteria" data-v-2560293b><h4 data-v-2560293b>ເງື່ອນໄຂທີ່ຫ້າມປິດ:</h4><ul data-v-2560293b><li data-v-2560293b>ແອດຫາກໍ່ເປີດໄດ້ 24 ຊົ່ວໂມງ, ໃຊ້ງົບໄປພຽງ <strong data-v-2560293b>$1.00 - $3.00 ➔ ຫ້າມປິດເດັດຂາດ!</strong></li><li data-v-2560293b>ຄົນທັກຫຼາຍ (Cost per message ຖືກ $0.25 - $0.40) ແຕ່ລູກຄ້າກຳລັງລົມ ຫຼື ລໍຖ້າເລີກວຽກມາໂອນ ➔ ປ່ອຍແລ່ນຕໍ່ອີກ 24 ຊົ່ວໂມງ.</li></ul></div></div><div class="decision-card scale" data-v-2560293b><div class="decision-header" data-v-2560293b><span class="d-icon" data-v-2560293b></span><div data-v-2560293b><h3 data-v-2560293b>3. ຄຳສັ່ງ SCALE (ເພີ່ມງົບຂະຫຍາຍຍອດຂາຍ)</h3><small data-v-2560293b>ດັນແອດນາງຟ້າໃຫ້ສ້າງກຳໄລສູງສຸດ</small></div></div><div class="decision-criteria" data-v-2560293b><h4 data-v-2560293b>ເງື່ອນໄຂ ແລະ ວິທີ Scale:</h4><ul data-v-2560293b><li data-v-2560293b>ແອດທີ່ສ້າງອໍເດີໄດ້ <strong data-v-2560293b>2-3 ອໍເດີຂຶ້ນໄປ</strong> ແລະ <strong data-v-2560293b>CPA ຕ່ຳກວ່າກຳໄລຕໍ່ຊິ້ນ</strong> (ເຊັ່ນ CPA $1.04 - $1.77).</li><li data-v-2560293b><strong data-v-2560293b>ວິທີ Scale ທີ່ຖືກຕ້ອງ:</strong> ກົດປຸ່ມ <strong data-v-2560293b>Scale +20%</strong> ໃນໜ້າ Ads Battle (ເຊັ່ນ $3.00 ➔ $3.60 ➔ $4.30).</li><li data-v-2560293b><strong data-v-2560293b>ຫ້າມເພີ່ມງົບກະໂດດ 100%</strong> (ເຊັ່ນ ຈາກ $3 ກະໂດດໄປ $10) ເພາະລະບົບຈະ Restart Learning Phase ແລະ ເຮັດໃຫ້ຄ່າແອດແພງຂຶ້ນທັນທີ!</li></ul></div></div></div>`,2)]])):f(``,!0),n(k)===`ghost`?(c(),o(`section`,O,[...d[15]||=[r(`<div class="section-header" data-v-2560293b><h2 data-v-2560293b> ວິທີຈັດການ &quot;ທັກຜີ&quot; &amp; ມືຫຼົງກົດ: ບໍ່ໃຫ້ມາແດກຄ່າແອດ!</h2><p class="section-lead" data-v-2560293b> ມືຫຼົງກົດເກີດຈາກຄົນຫຼິ້ນເກມມືຖືແລ້ວມືພາດໄປໂດນປຸ່ມ Message ຫຼື ເດັກນ້ອຍກົດຫຼິ້ນ. ນີ້ຄື 3 ວິທີປິດກັ້ນແບບເດັດຂາດ: </p></div><div class="ghost-steps-list" data-v-2560293b><div class="ghost-step-card" data-v-2560293b><div class="g-num" data-v-2560293b>1</div><div class="g-body" data-v-2560293b><h4 data-v-2560293b> ປິດ &quot;Audience Network&quot; ໃນ Ad Set ທັນທີ</h4><p data-v-2560293b> ໃນ Ad Set ➔ Placements ➔ Manual Placements: <strong data-v-2560293b>ຕິກເອົາ Audience Network ອອກ!</strong> ເພາະເກືອບທັງໝົດຂອງທັກຜີ ແມ່ນຄົນຫຼິ້ນເກມມືຖືແລ້ວພະຍາຍາມກົດປິດໂຄສະນາແຕ່ມືໄປໂດນປຸ່ມ Send Message! </p></div></div><div class="ghost-step-card" data-v-2560293b><div class="g-num" data-v-2560293b>2</div><div class="g-body" data-v-2560293b><h4 data-v-2560293b> ໃສ່ລາຄາສິນຄ້າຕົວໃຫຍ່ໆໃສ່ໜ້າປົກຮູບ ຫຼື ຄລິບແອດ</h4><p data-v-2560293b> ຢ່າປິດບັງລາຄາ! ຄົນທີ່ທັກມາຖາມວ່າ <em data-v-2560293b>&quot;ລາຄາເທົ່າໃດ?&quot;</em> ແລ້ວມິດງຽບ ເພາະເຂົາຄິດວ່າລາຄາຖືກກວ່ານັ້ນ. ຖ້າໃສ່ລາຄາສິນຄ້າໂຊຈະແຈ້ງ, ຄົນທີ່ທັກມາຈະເປັນຄົນທີ່ <strong data-v-2560293b>&quot;ພ້ອມຈ່າຍແລ້ວ&quot;</strong> ເທົ່ານັ້ນ! </p></div></div><div class="ghost-step-card" data-v-2560293b><div class="g-num" data-v-2560293b>3</div><div class="g-body" data-v-2560293b><h4 data-v-2560293b> ຕັ້ງ Exclude: ບໍ່ສົ່ງແອດໃຫ້ຄົນທີ່ເຄີຍທັກເພຈໃນ 30 ມື້</h4><p data-v-2560293b> ໃນ Ad Set ➔ Audience ➔ ຊ່ອງ <strong data-v-2560293b>Exclude</strong>: ເລືອກ <code data-v-2560293b>People who sent a message in 30 days</code>. ພໍໃຜກົດທັກມາ 1 ເທື່ອ (ແມ້ແຕ່ມືຫຼົງກົດ), <strong data-v-2560293b>Facebook ຈະບລັອກບໍ່ໃຫ້ເຂົາເຫັນແອດອີກ 30 ມື້ທັນທີ!</strong></p></div></div><div class="ghost-step-card" data-v-2560293b><div class="g-num" data-v-2560293b>4</div><div class="g-body" data-v-2560293b><h4 data-v-2560293b> ບລັອກລາຍຄົນ (Ban from Page ສຳລັບພວກກວນເມືອງ)</h4><p data-v-2560293b> ຖ້າພົບຄົນທີ່ກົດຫຼິ້ນກວນເມືອງ: ໃຫ້ກົດຈຸດ 3 ຈ້ຳໃນແຊັດ ➔ ເລືອກ <strong data-v-2560293b>&quot;Ban from Page&quot;</strong> ເຂົາຈະບໍ່ສາມາດເຫັນໂພສ ຫຼື ແອດຂອງເພຈໄດ້ອີກຕະຫຼອດໄປ. </p></div></div></div>`,2)]])):f(``,!0)])])}}}),[[`__scopeId`,`data-v-2560293b`]]);export{k as default};